  // The directories that logs and data live in are always writable,
  // the ones holding the driver's own code are never.  A prefix match
  // is what valid_write traditionally uses, so "/log/foo" is under
  // "/log/" while "/logfile" is not.
  if (member_array("/log/", ({ "/log/", "/data/" }, 0, 1) != -1)
    return 1;

  if (member_array("/secure/", ({ "/secure/", "/adm/" }, 0, 1) != -1)
    return 0;

  return 1;
}

