private nosave object template_ob;

// The template every virtual object is cloned from.  A mudlib would keep it
// under a daemon directory; in this test mudlib /clone/void is the template.
private string template_path() {
  return "/clone/void";
}

private object get_template() {
  if (!objectp(template_ob)) {
    template_ob = load_object(template_path());
  }
  return template_ob;
