// Does 'file' look like a virtual path?  Returns true for
// "/<dom>/virtual/<name>_<x>_<y>" with non-empty <dom> and <name>, and
// digits for <x> and <y>.
public int is_virtual_path(string file) {
  string *parts, dom, file_name_part;

  if (!stringp(file) || file[0] != '/') {
    return 0;
  }

  parts = explode(file, "/");
  // "/d/virtual/map_1_2" -> ({ "", "d", "virtual", "map_1_2" })
  if (sizeof(parts) != 4 || parts[3] == "") {
    return 0;
  }

  dom = parts[1];
  if (dom == "" || parts[2] != "virtual") {
    return 0;
  }

  file_name_part = parts[3];
  if (sscanf(file_name_part, "%s_%d_%d", dom, parts[1], parts[2]) != 3) {
    return 0;
  }
  // "%s" is greedy, so the only way the above can fail on "a_1_2" is a
  // missing name or a non-numeric tail; check the name is not empty.
  if (dom == "") {
    return 0;
  }

  return 1;
}

// compile_object(string file) - mudlib answer for a filename the driver could
// not find on disk.  Returns the object to associate with 'file', or 0.
public mixed compile_object(string file) {
  object tmpl, ob;

  if (!is_virtual_path(file)) {
    return 0;
  }

  tmpl = get_template();
  if (!tmpl) {
    return 0;
  }

  // The driver turns the returned clone into a virtual object: it renames it
  // to 'file', marks it virtual, and caches it, so a later load_object(file)
  // finds this very object.
  ob = clone_object(tmpl);
  if (!ob) {
    return 0;
  }

  return ob;
}

